program.source:
Algoritmo Primo
  Definir n Como Entero;
  Leer n;
  Definir esPrimo Como Logico <- Verdadero;
  Para d <- 2 Hasta n - 1 Hacer
    Si n mod d = 0 Entonces
      esPrimo <- Falso;
      Salir;
    FinSi
  FinPara
  Si esPrimo Entonces
    Escribir "Es primo";
  Sino
    Escribir "No es primo";
  FinSi
FinAlgoritmo

